styles:
:root{--bg:#080808;--paper:#f1eee7;--ink:#f5f2ec;--muted:#a8a49c;--line:#2a2927;--yes:#ee1749;--ease:cubic-bezier(.16,1,.3,1)}
*{box-sizing:border-box}html{scroll-behavior:smooth;background:var(--bg)}body{margin:0;background:var(--bg);color:var(--ink);font-family:"Helvetica Neue",Helvetica,Arial,sans-serif;overflow-x:hidden}a{color:inherit;text-decoration:none}img{display:block;max-width:100%}.wrap{width:min(1380px,calc(100% - 64px));margin:auto}.nav{position:fixed;z-index:100;top:18px;left:50%;transform:translateX(-50%);width:min(1380px,calc(100% - 64px));height:58px;border:1px solid #2b2b2b;background:rgba(8,8,8,.82);backdrop-filter:blur(16px);display:flex;align-items:center;justify-content:space-between;padding:0 18px}.nav img{width:116px}.navlinks{display:flex;gap:24px;font-size:12px;color:#b8b5ae}.navcta{border:1px solid #444;padding:10px 14px;font-size:11px;text-transform:uppercase;letter-spacing:.12em}.hero{min-height:100svh;padding:134px 0 66px;display:grid;align-items:end;position:relative}.hero-grid{display:grid;grid-template-columns:1.05fr .95fr;gap:28px;align-items:end}.eyebrow{font-size:11px;text-transform:uppercase;letter-spacing:.19em;color:#a8a49c;margin-bottom:20px}.hero h1{font-size:clamp(72px,9.2vw,162px);line-height:.82;letter-spacing:-.075em;margin:0;max-width:900px}.hero h1 em{font-style:normal;color:var(--yes)}.lead{font-size:clamp(18px,1.45vw,24px);line-height:1.45;color:#c9c5bd;max-width:600px;margin:28px 0 0}.hero-card{position:relative;aspect-ratio:1.08;border:1px solid #262626;overflow:hidden;background:#eae7df url("assets/yes-project-cover.png") center/cover no-repeat}.hero-card img{width:100%;height:100%;object-fit:cover;object-position:top;opacity:0;transition:opacity .5s ease,transform 1.2s var(--ease)}.hero-card img.loaded{opacity:1}.hero-card:hover img{transform:scale(1.025)}.hero-card:after{content:"Fahrschule YES! · Velbert";position:absolute;left:18px;bottom:18px;background:#090909;color:#fff;padding:10px 12px;font-size:10px;letter-spacing:.14em;text-transform:uppercase}.hero-foot{display:flex;justify-content:space-between;gap:24px;margin-top:46px;padding-top:16px;border-top:1px solid var(--line);font-size:11px;text-transform:uppercase;letter-spacing:.14em;color:#8d8a84}.snapshot{background:var(--paper);color:#0a0a0a;padding:110px 0}.snapshot-grid{display:grid;grid-template-columns:.8fr 1.2fr;gap:12vw}.snapshot h2,.section-title{font-size:clamp(54px,6.3vw,104px);line-height:.92;letter-spacing:-.06em;margin:0}.snapshot p{font-size:22px;line-height:1.48;margin:0 0 28px;max-width:740px}.facts{display:grid;grid-template-columns:repeat(2,1fr);border-top:1px solid #bbb6ae}.fact{padding:18px 0;border-bottom:1px solid #bbb6ae}.fact small{display:block;font-size:10px;text-transform:uppercase;letter-spacing:.16em;color:#746f68;margin-bottom:8px}.fact strong{font-size:18px;font-weight:500}.manifesto{padding:140px 0 110px;position:relative;overflow:hidden}.manifesto .big{font-size:clamp(80px,12.5vw,230px);line-height:.74;letter-spacing:-.08em;margin:0;color:#f3f0ea}.manifesto .big.outline{-webkit-text-stroke:1px #67635d;color:transparent;margin-left:9vw}.manifesto-copy{display:grid;grid-template-columns:1fr 1fr;gap:8vw;margin-top:100px;align-items:start}.manifesto-copy p{font-size:21px;line-height:1.55;color:#bcb7ae;max-width:640px}.pinkline{width:80px;height:4px;background:var(--yes);margin-top:12px}.story{position:relative;padding:110px 0 160px}.story-head{display:grid;grid-template-columns:.8fr 1.2fr;gap:12vw;margin-bottom:84px}.story-head p{font-size:20px;line-height:1.55;color:#aba79f;max-width:650px;margin-top:8px}.story-grid{display:grid;grid-template-columns:1.18fr .82fr;gap:5vw;align-items:start}.browser{position:sticky;top:96px;aspect-ratio:16/10;border:1px solid #303030;background:#121212;overflow:hidden;box-shadow:0 24px 80px rgba(0,0,0,.25)}.browser-bar{height:42px;background:#111;border-bottom:1px solid #2a2a2a;display:flex;align-items:center;gap:6px;padding:0 13px;position:relative;z-index:5}.dot{width:7px;height:7px;border-radius:50%;background:#555}.address{font-size:10px;color:#777;margin-left:8px}.shot{position:absolute;inset:42px 0 0;opacity:0;visibility:hidden;transform:scale(1.01);transition:opacity .48s var(--ease),transform .8s var(--ease);background:#eae7df}.shot.active{opacity:1;visibility:visible;transform:scale(1)}.shot img{width:100%;height:100%;object-fit:cover;object-position:top center;opacity:0;transition:opacity .35s ease}.shot.loaded img{opacity:1}.shot.loaded .fallback{display:none}.shot .fallback{position:absolute;inset:0;display:grid;place-items:center;color:#111;text-align:center;padding:30px;background:#ebe7df}.shot .fallback b{font-size:clamp(38px,5vw,80px);letter-spacing:-.06em}.shot .fallback span{display:block;color:var(--yes)}.steps{position:relative}.step{min-height:74vh;padding:10vh 0 14vh;border-top:1px solid var(--line);opacity:.34;transition:opacity .35s ease}.step.active{opacity:1}.step .n{font-size:11px;letter-spacing:.18em;color:var(--yes);text-transform:uppercase}.step h3{font-size:clamp(48px,4.8vw,84px);line-height:.92;letter-spacing:-.055em;margin:18px 0 24px}.step p{max-width:580px;font-size:18px;line-height:1.55;color:#aaa59d}.step ul{list-style:none;padding:0;margin:28px 0 0;border-top:1px solid #2d2c2a}.step li{padding:12px 0;border-bottom:1px solid #2d2c2a;font-size:13px;color:#d3cfc8;display:flex;justify-content:space-between}.step li:after{content:"↗";color:var(--yes)}.routes{background:var(--paper);color:#090909;padding:130px 0}.routes-head{display:grid;grid-template-columns:1fr 1fr;gap:8vw;margin-bottom:70px}.routes-head p{font-size:20px;line-height:1.55;max-width:650px}.route-list{border-top:1px solid #aaa59e}.route{display:grid;grid-template-columns:90px 1.25fr .75fr;gap:30px;padding:34px 0;border-bottom:1px solid #aaa59e;align-items:center;transition:padding .35s var(--ease),background .35s}.route:hover{padding-left:18px;background:#e8e3da}.route .num{font-size:11px;letter-spacing:.16em}.route h3{font-size:clamp(32px,4vw,62px);letter-spacing:-.05em;margin:0}.route p{font-size:15px;line-height:1.5;margin:0;color:#5e5952}.visual-band{padding:0;background:var(--paper)}.website-reveal{width:min(1500px,calc(100% - 48px));margin:auto;aspect-ratio:16/8.4;overflow:hidden;border:1px solid #b9b4ac;background:#eee url("assets/yes-project-cover.png") center/cover no-repeat}.website-reveal img{width:100%;height:100%;object-fit:cover;object-position:top center;transition:transform 8s cubic-bezier(.2,.7,.2,1)}.website-reveal:hover img{transform:translateY(-23%)}.proof{padding:140px 0;background:var(--paper);color:#090909}.proof-grid{display:grid;grid-template-columns:1fr 1fr;gap:10vw}.proof h2{font-size:clamp(58px,7vw,118px);line-height:.88;letter-spacing:-.065em;margin:0}.proof-copy{padding-top:18px}.proof-copy p{font-size:22px;line-height:1.5;margin:0 0 34px}.proof-list{border-top:1px solid #aaa59e}.proof-list div{display:flex;justify-content:space-between;padding:16px 0;border-bottom:1px solid #aaa59e;font-size:13px}.local{padding:150px 0;position:relative;overflow:hidden}.local:before{content:"VELBERT";position:absolute;right:-.04em;bottom:-.15em;font-size:26vw;letter-spacing:-.08em;color:#111;line-height:.8;pointer-events:none}.local-grid{position:relative;z-index:2;display:grid;grid-template-columns:.8fr 1.2fr;gap:12vw}.local h2{font-size:clamp(58px,7vw,120px);line-height:.88;letter-spacing:-.065em;margin:0}.local p{font-size:20px;line-height:1.58;color:#aaa59d;max-width:680px}.cta{background:var(--yes);color:#080808;padding:120px 0}.cta .wrap{display:grid;grid-template-columns:1.25fr .75fr;gap:10vw;align-items:end}.cta h2{font-size:clamp(64px,8vw,140px);line-height:.84;letter-spacing:-.075em;margin:0}.cta p{font-size:20px;line-height:1.5;max-width:520px}.btn{display:inline-flex;margin-top:20px;padding:14px 17px;border:1px solid #111;font-size:11px;text-transform:uppercase;letter-spacing:.15em}.next{padding:110px 0}.next a{display:flex;justify-content:space-between;align-items:end;border-top:1px solid var(--line);padding-top:28px}.next small{font-size:10px;letter-spacing:.16em;text-transform:uppercase;color:#888}.next strong{font-size:clamp(48px,6vw,100px);letter-spacing:-.055em}.next i{font-style:normal;font-size:48px;color:var(--yes)}footer{border-top:1px solid var(--line);padding:36px 0 48px;color:#777;font-size:11px}.mobile-shot{display:none;position:relative;background:#e8e5de}.mobile-shot:before{content:attr(data-label);position:absolute;inset:0;display:grid;place-items:center;text-align:center;padding:20px;color:#111;font-size:22px;font-weight:600;letter-spacing:-.03em}.mobile-shot img{position:relative;z-index:1;opacity:0}.mobile-shot.loaded img{opacity:1}.mobile-shot.loaded:before{display:none}
@media(max-width:1050px){.wrap{width:min(100% - 40px,980px)}.nav{width:calc(100% - 40px)}.navlinks{display:none}.hero-grid,.snapshot-grid,.story-head,.routes-head,.proof-grid,.local-grid,.cta .wrap{grid-template-columns:1fr}.hero{min-height:auto;padding-top:130px}.hero-card{max-width:720px;margin-top:40px}.story-grid{grid-template-columns:1fr 1fr;gap:32px}.browser{top:86px}.step h3{font-size:clamp(40px,6vw,64px)}.route{grid-template-columns:60px 1.1fr .9fr}.manifesto-copy{grid-template-columns:1fr 1fr;gap:40px}}
@media(max-width:820px){.nav{top:10px;width:calc(100% - 24px);height:54px}.wrap{width:calc(100% - 30px)}.hero{padding-top:112px}.hero h1{font-size:clamp(62px,18vw,112px)}.hero-grid{gap:10px}.hero-foot{flex-direction:column}.snapshot,.routes,.proof,.local{padding:90px 0}.manifesto{padding:100px 0 70px}.manifesto .big{font-size:17vw;line-height:.82}.manifesto .big.outline{margin-left:0;font-size:13.8vw}.manifesto-copy{grid-template-columns:1fr;margin-top:60px}.story{padding:80px 0}.story-head{margin-bottom:38px}.story-grid{display:block}.browser{display:none}.steps{display:grid;gap:46px}.step{min-height:0;padding:0 0 32px;opacity:1}.step h3{font-size:clamp(44px,12vw,70px)}.mobile-shot{display:block;margin:22px 0 4px;aspect-ratio:16/10;border:1px solid #2c2c2c;overflow:hidden;background:#e8e5de}.mobile-shot img{width:100%;height:100%;object-fit:cover;object-position:top}.route{grid-template-columns:42px 1fr}.route p{grid-column:2}.website-reveal{width:calc(100% - 24px);aspect-ratio:4/5}.website-reveal img{object-fit:cover}.proof h2,.local h2{font-size:15vw}.cta{padding:90px 0}.cta h2{font-size:17vw}.next a{display:grid;grid-template-columns:1fr auto;gap:12px}.next small{grid-column:1/3}.next strong{font-size:14vw}.navcta{padding:8px 10px}.hero-card:after{font-size:9px}.lead{font-size:18px}.snapshot p,.routes-head p,.proof-copy p,.local p,.cta p{font-size:18px}}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}.shot,.step,.hero-card img,.website-reveal img{transition:none!important}}

/* AROZ R2 – detail craft / accessibility; scoped additions only. */
html { scroll-padding-top: 90px; }
:where(h1,h2,h3) { text-wrap: balance; }
:where(p,li,dd) { overflow-wrap: break-word; }
:where(a, button, input, select, textarea):focus-visible { outline: 2px solid #ff4164; outline-offset: 4px; box-shadow: 0 0 0 2px rgba(0,0,0,.5); }
:where(button, input, textarea, select) { font: inherit; }
:where(img) { max-width:100%; }
@media(prefers-reduced-motion:reduce){ html{scroll-behavior:auto!important} *,*::before,*::after{animation-duration:.01ms!important;transition-duration:.01ms!important;scroll-behavior:auto!important} }
@media(max-width:620px){
 :where(h1,h2,h3) { hyphens:auto; overflow-wrap:normal; }
 :where(p) { line-height:1.55; }
 :where(a,button) { -webkit-tap-highlight-color:transparent; }
}

/* Typography AA craft floor for legacy 8-10px labels */
.fact small{font-size:12px!important}
.address{font-size:12px!important}
.next small{font-size:12px!important}


/* P0: avoid duplicate caption over lettering already contained in YES artwork. */
.hero-card:after{display:none!important}
.hero-card{background-color:#e9e5dc;isolation:isolate}
.fact small{font-size:12px;color:#55504a}
.address{font-size:12px;color:#b9b1a7}
.next small{font-size:12px;color:#b8b2aa}
.eyebrow{font-size:12px}
@media(max-width:820px){
 .hero-card{aspect-ratio:1.16;margin-top:24px}
 .hero h1{font-size:clamp(55px,14vw,99px);line-height:.98}
 .snapshot h2,.section-title{font-size:clamp(45px,12vw,70px);line-height:1.02}
 .manifesto .big{font-size:clamp(39px,12.5vw,86px);line-height:1.02}
 .manifesto .big.outline{font-size:clamp(38px,11vw,80px)}
 .step{padding-bottom:22px}
 .step h3{font-size:clamp(39px,10.5vw,60px);line-height:1}
 .mobile-shot{aspect-ratio:4/3}
 .next strong{font-size:clamp(36px,10.5vw,64px);line-height:1.04}
 .route{gap:14px}
 .route h3{font-size:clamp(31px,8vw,48px)}
}

/* Intentional branded editorial panels – not counterfeit website screenshots. */
.shot .fallback.editorial-panel{display:flex;flex-direction:column;align-items:flex-start;justify-content:flex-end;padding:clamp(24px,4vw,58px);background:#ece8df;color:#0c0c0d;gap:14px;text-align:left}
.shot:nth-child(2) .editorial-panel{background:#e81848;color:#fff}
.shot:nth-child(3) .editorial-panel{background:#171619;color:#fff}
.shot:nth-child(4) .editorial-panel{background:#e7e3dc;color:#0c0c0d}
.shot:nth-child(5) .editorial-panel{background:#eeeae3;color:#101012}
.editorial-panel .editorial-kicker{font-size:12px;letter-spacing:.12em;text-transform:uppercase;color:inherit}
.shot .fallback.editorial-panel b{font-size:clamp(35px,4.3vw,70px);line-height:.94;letter-spacing:-.06em}
.shot .fallback.editorial-panel small{font-size:16px;font-weight:400;letter-spacing:0}
.mobile-shot.mobile-note{position:relative;display:flex;flex-direction:column;justify-content:space-between;align-items:flex-start;padding:clamp(24px,5vw,42px);aspect-ratio:auto;min-height:215px;gap:14px;border:0;background:#e8e4dd;color:#0b0b0d}
.mobile-shot.mobile-note::before{display:none!important}
.mobile-note span{font-size:12px;letter-spacing:.16em;text-transform:uppercase}
.mobile-note strong{font-weight:600;letter-spacing:-.065em;font-size:clamp(40px,10vw,66px);line-height:.95}
.mobile-note p{font-size:15px;line-height:1.5;margin:0}
.step:nth-child(2) .mobile-note{background:#e81848;color:#fff}
.step:nth-child(3) .mobile-note{background:#e9e5dd;color:#111}
.step:nth-child(4) .mobile-note{background:#1d1c1e;color:#eeeae3;border:1px solid #494549}
.website-reveal{aspect-ratio:1.8;background:#e9e5dd}
.website-reveal img{object-fit:contain;background:#e9e5dd}
@media(max-width:820px){.website-reveal{aspect-ratio:4/5}.website-reveal img{object-fit:cover;object-position:50% 0}.hero-card img{object-fit:contain;background:#e9e5dd}.mobile-note strong{overflow-wrap:break-word}}

.r11-skip{position:fixed;z-index:99999;top:9px;left:12px;padding:12px 17px;border:2px solid #fff;background:#101014;color:#fff;font:700 15px/1.25 Arial,sans-serif;text-decoration:none;transform:translateY(-160%)}
.r11-skip:focus-visible{transform:none;outline:3px solid #ff4164;outline-offset:3px}
